import { Component, OnInit, input, numberAttribute, signal } from '@angular/core';
import { IonContent, IonIcon } from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { checkmarkCircle, closeCircle } from 'ionicons/icons';

/**
 * Bounce page shown after Stripe checkout.
 * - fromApp=true: Immediately redirects via heybible:// custom scheme to return to native app.
 *   Falls back to "close this tab" hint if the redirect doesn't work.
 * - fromApp not set (web): Shows message + "Return to account" link.
 */
@Component({
  selector: 'app-checkout-redirect',
  template: `
    <ion-content class="ion-padding">
      <div class="container">
        <ion-icon [name]="icon()" [color]="iconColor()" class="status-icon"></ion-icon>
        <h2>{{ title() }}</h2>
        <p>{{ message() }}</p>
        @if (showCloseHint()) {
          <p class="hint">You can close this tab to return to Hey Bible.</p>
        }
        @if (showWebContinue()) {
          <a href="/account" class="continue-link">Return to account</a>
        }
      </div>
    </ion-content>
  `,
  styles: [`
    .container {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100%;
      gap: 12px;
      max-width: 300px;
      margin: 0 auto;
      text-align: center;
    }
    .status-icon {
      font-size: 64px;
    }
    h2 {
      margin: 0;
      font-size: 22px;
      font-weight: 600;
    }
    p {
      margin: 0;
      color: var(--ion-color-medium);
      font-size: 16px;
    }
    .hint {
      margin-top: 8px;
      font-size: 14px;
      color: var(--ion-color-medium-shade);
    }
    .continue-link {
      margin-top: 16px;
      color: var(--ion-color-primary);
      font-size: 16px;
    }
  `],
  standalone: true,
  imports: [IonContent, IonIcon],
})
export class CheckoutRedirectPage implements OnInit {
  // Query params
  success = input<string>();
  credits = input(0, { transform: numberAttribute });
  cancelled = input<string>();
  fromApp = input<string>();

  // State
  title = signal('');
  message = signal('');
  icon = signal('checkmark-circle');
  iconColor = signal('success');
  showCloseHint = signal(false);
  showWebContinue = signal(false);

  constructor() {
    addIcons({ checkmarkCircle, closeCircle });
  }

  ngOnInit() {
    const isFromApp = this.fromApp() === 'true';

    if (this.success() === 'true') {
      this.icon.set('checkmark-circle');
      this.iconColor.set('success');
      this.title.set('Purchase Complete!');
      this.message.set('Your credits will appear shortly.');
    } else {
      this.icon.set('close-circle');
      this.iconColor.set('medium');
      this.title.set('Purchase Cancelled');
      this.message.set('No charges were made.');
    }

    if (isFromApp) {
      // Build the custom URL scheme deep link
      const deepLink = this.success() === 'true'
        ? `heybible://purchase-complete?credits=${this.credits()}`
        : 'heybible://purchase-cancelled';

      // Attempt to redirect back into the native app
      window.location.href = deepLink;

      // If we're still here after a short delay, the redirect didn't close the browser
      // Show fallback hint to close manually
      setTimeout(() => {
        this.showCloseHint.set(true);
      }, 1000);
    } else {
      // Web flow: show link back to account
      this.showWebContinue.set(true);
    }
  }
}
